      "rung": 5,
      "purpose": "Monitor pallet at stop position photo-eye X10 and set pallet-in-position flag M100."
    },
    {
      "rung": 6,
      "purpose": "Latch stopper release solenoid Y11 on rising edge of line controller release request X14."
    },
    {
      "rung": 7,
      "purpose": "Time stopper release duration (2.0 s preset) while solenoid Y11 is energized."
    },
    {
      "rung": 8,
      "purpose": "Reset stopper release solenoid Y11 when duration timer T11 completes."
